<template><view class="p"><view class="nav"><text @click="back">‹</text><text>关闭平台通知</text><text @click="load">⟳</text></view><view class="hero"><text>批量关闭平台通知</text><button @click="run">立即执行</button></view><scroll-view scroll-y class="list"><view class="log" v-for="l in logs" :key="l.id"><text class="name">批次 #{{l.id}}</text><text>{{l.status||l.result||'-'}} · {{l.message||l.errorMsg||''}}</text><text class="time">{{l.createdAt||l.startedAt||''}}</text></view><view v-if="!logs.length" class="hint">暂无关闭通知日志</view></scroll-view></view></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{listCloseNoticeLogs,runCloseNoticeManually}from'@/api/bot';const logs=ref<any[]>([]);async function load(){try{const r:any=await listCloseNoticeLogs({page:1,size:50});logs.value=Array.isArray(r)?r:(r?.records||[])}catch(e:any){uni.showToast({title:e?.message||'加载失败',icon:'none'})}}async function run(){try{await runCloseNoticeManually();uni.showToast({title:'已触发',icon:'success'});load()}catch(e:any){uni.showToast({title:e?.message||'执行失败',icon:'none'})}}function back(){uni.navigateBack({fail:()=>uni.switchTab({url:'/pages/profile/index'})})}onMounted(load)</script><style scoped lang="scss">.p{min-height:100vh;background:#f5f5f7}.nav{height:88rpx;background:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 24rpx;font-size:32rpx;font-weight:700}.nav text:first-child{font-size:48rpx;color:#6b7280}.nav text:last-child{font-size:34rpx;color:#4f46e5}.hero{margin:24rpx;padding:32rpx;border-radius:28rpx;background:linear-gradient(135deg,#f97316,#ef4444);color:#fff;display:flex;justify-content:space-between;align-items:center}.hero text{font-size:30rpx;font-weight:800}.hero button{background:#fff;color:#ef4444;border-radius:32rpx;font-size:24rpx}.list{height:calc(100vh - 220rpx);padding:0 24rpx}.log{background:#fff;border-radius:20rpx;padding:24rpx;margin-bottom:16rpx;display:flex;flex-direction:column;gap:8rpx;color:#6b7280}.name{font-weight:700;color:#111827}.time{font-size:22rpx;color:#9ca3af}.hint{text-align:center;color:#9ca3af;padding:40rpx}</style>